<?php require __DIR__.'/includes/bootstrap.php';$ids=array_values(array_unique(array_map('intval',$_SESSION['compare']??[])));$products=[];if($ids){$ph=implode(',',array_fill(0,count($ids),'?'));$st=db()->prepare("SELECT p.*,c.name category_name FROM products p JOIN categories c ON c.id=p.category_id WHERE p.id IN ($ph)");$st->execute($ids);$products=$st->fetchAll();}$title='Compare';require __DIR__.'/includes/header.php';?><div class="max-w-[1480px] mx-auto px-3 sm:px-5 py-10"><div class="flex items-center justify-between mb-6"><h1 class="text-3xl font-black">Compare Products</h1><a href="/category.php?niche=gadgets" class="font-bold">Continue shopping</a></div><?php if(!$products):?><div class="py-20 text-center bg-white border rounded-2xl">No products selected for comparison.</div><?php else:?><div class="overflow-x-auto bg-white border rounded-2xl"><table class="w-full min-w-[760px]"><thead><tr><?php foreach($products as $p):?><th class="p-5 text-left border-l"><?=e($p['name'])?></th><?php endforeach;?></tr></thead><tbody><tr><?php foreach($products as $p):?><td class="p-5 border-l"><div class="aspect-square bg-slate-100 rounded-2xl overflow-hidden"><img src="<?=e(image_or_placeholder(null,$p['name']))?>" class="w-full h-full object-cover"></div><div class="font-black mt-3">Price: <?=money($p['price'])?></div><div class="text-sm text-slate-500 mt-2">Category: <?=e($p['category_name'])?></div><div class="text-sm text-slate-500 mt-2">SKU: <?=e($p['sku'])?></div></td><?php endforeach;?></tr></tbody></table></div><?php endif;?></div><?php require __DIR__.'/includes/footer.php'; ?>
